(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const modules = [
    ['catalog','Fanlar katalogi','Fan kodlari, kredit diapazoni, oldindan talablar va versiyalar.','P0'],
    ['groups','Guruh va potoklar','Guruh kontingenti, ma’ruza potoklari va laboratoriya kichik guruhlari.','P0'],
    ['department','Kafedra yuklamasi','Talab, taqsimlangan va bo‘sh yuklamaning alohida balansi.','P0'],
    ['execution','Ijro monitoringi','Reja va tekshirilgan fakt. Dalilsiz ish bajarilgan deb hisoblanmaydi.','P1'],
    ['import','Import markazi','Fayl → moslashtirish → validatsiya → preview → solishtirish → commit.','P0'],
    ['versions','Versiyalar va stsenariylar','Tasdiqlangan tarix o‘zgarmaydi; o‘zgarish uchun yangi revision.','P1'],
    ['users','Foydalanuvchilar va vakolatlar','Rol, fakultet, kafedra, akademik yil va hujjat holati bo‘yicha ruxsat.','P0'],
    ['integrations','Integratsiya va xabarnomalar','Tasdiqlangan API, idempotent jarayonlar va konfliktlar navbati.','P1'],
    ['schedule','Dars jadvali va auditoriyalar','O‘qituvchi, guruh, xona sig‘imi va bandlik konfliktlari.','P2'],
    ['syllabus','Sillabus va metodik ta’minot','Fan dasturi, materiallar versiyasi va tasdiqlangan rejaga moslik.','P2'],
    ['practice','Amaliyotlar nazorati','Davr, mas’ul, guruhlar, dalillar va yakuniy hisobot.','P2'],
    ['quality','Ta’lim sifati monitoringi','Kuzatuv, checklist, tuzatish vazifasi va qayta tekshirish.','P2'],
    ['forecast','Resurslar prognozi','Kelgusi yil ehtiyoji va mavjud imkoniyatlar farqi; tavsiyaviy stsenariy.','P2'],
    ['system','Tizim holati','Muhit, saqlash, hisoblash yadrosi va tayyorlik chegaralari.','Admin']
  ];
  const nav = document.querySelector('nav');
  const caption = document.createElement('div'); caption.className='side-caption';caption.textContent='MODULLAR XARITASI';nav.append(caption);
  const mapBtn=document.createElement('button');mapBtn.className='nav-item';mapBtn.dataset.page='modules';mapBtn.innerHTML='<span>▦</span> Barcha modullar';nav.append(mapBtn);
  const map=document.createElement('section');map.className='page';map.id='page-modules';map.innerHTML='<div class="page-head"><div><div class="eyebrow">PLATFORMANING TO‘LIQ XARITASI</div><h1>Barcha modullar</h1><p>TTZ modullari va ularning joriy holati. Kartani ochib talablarni ko‘ring.</p></div><span class="tag amber">Rasmiy tizim emas</span></div><div class="module-list"></div>';
  document.querySelector('main').append(map);
  for(const [id,title,desc,phase] of modules){
    const card=document.createElement('article');card.className='panel';const badge=document.createElement('span');badge.className='tag';badge.textContent=phase+' · Rejalashtirilgan';const h=document.createElement('h2');h.textContent=title;h.style.marginTop='15px';const p=document.createElement('p');p.textContent=desc;const b=document.createElement('button');b.className='text-btn';b.dataset.page=id;b.textContent='Talablarni ko‘rish →';card.append(badge,h,p,b);map.querySelector('.module-list').append(card);
    const page=document.createElement('section');page.className='page';page.id='page-'+id;
    const head=document.createElement('div');head.className='page-head';const heading=document.createElement('div');const eye=document.createElement('div');eye.className='eyebrow';eye.textContent='MODUL / '+phase;const titleNode=document.createElement('h1');titleNode.textContent=title;const sub=document.createElement('p');sub.textContent=desc;heading.append(eye,titleNode,sub);head.append(heading);
    const panel=document.createElement('div');panel.className='panel';panel.innerHTML='<span class="tag amber">Ishlab chiqish kutilmoqda</span><h2 style="margin-top:20px">Rasmiy ish jarayoni hali yoqilmagan</h2><p class="muted">Bu ekran modul doirasini ko‘rsatadi. Server, ruxsat nazorati va haqiqiy manbalar ulanmaguncha rasmiy ma’lumot yaratish yoki tasdiqlash mumkin emas.</p><button class="btn subtle" data-page="modules">← Modullar xaritasi</button>';
    if(id==='import') panel.innerHTML+='<div class="flow-strip"><div>1. Fayl</div><span>→</span><div>2. Moslashtirish</div><span>→</span><div>3. Dry-run</div><span>→</span><div>4. Solishtirish</div><span>→</span><div>5. Commit</div></div><p class="muted small">Haqiqiy Excel andozasi, atomar import servisi va audit kerak. Ushbu demoda fayl yuborish o‘chirilgan; hech qanday fayl tashqi xizmatga uzatilmaydi.</p>';
    if(id==='system') panel.innerHTML+='<div class="detail-grid space-top"><div><small>Muhit</small><strong>Lokal interaktiv demo</strong></div><div><small>Saqlash</small><strong>Ushbu brauzer / localStorage</strong></div><div><small>Server autentifikatsiyasi</small><strong>Ulanmagan</strong></div><div><small>Rasmiy hisob</small><strong>Bloklangan</strong></div></div>';
    page.append(head,panel);document.querySelector('main').append(page);
  }
  const names={modules:'Barcha modullar',...Object.fromEntries(modules.map(m=>[m[0],m[1]]))};
  document.querySelectorAll('.nav-item[data-page]').forEach(b=>{if(!names[b.dataset.page]) names[b.dataset.page]=b.textContent.trim().replace(/^\S+\s/,'');});
  function go(id){if(!$('page-'+id))return;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+id));document.querySelectorAll('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.page===id);if(b.dataset.page===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(names[id])$('crumb-title').textContent=names[id];$('sidebar').classList.remove('open');history.replaceState(null,'','#'+id);window.scrollTo(0,0);}
  document.addEventListener('click',e=>{const el=e.target.closest('[data-page],[data-goto]');if(el)go(el.dataset.page||el.dataset.goto);});
  const dialog=$('search-dialog');
  function results(){const q=$('module-search').value.toLocaleLowerCase();$('search-results').replaceChildren();for(const [id,name] of Object.entries(names)){if(!name.toLocaleLowerCase().includes(q))continue;const b=document.createElement('button');b.textContent=name;b.onclick=()=>{go(id);dialog.close();};$('search-results').append(b);}if(!$('search-results').children.length)$('search-results').textContent='Modul topilmadi. Boshqa nom bilan qidiring.';}
  $('search-open').onclick=()=>{results();dialog.showModal();$('module-search').focus();};$('search-close').onclick=()=>dialog.close();$('module-search').oninput=results;
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search-open').click();}if(e.key==='Escape')$('sidebar').classList.remove('open');});
  let timer;function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',4000);}
  const demo=[{name:'O‘zbek tilshunosligi',faculty:'O‘zbek filologiyasi',term:'1-semestr',year:'2026/2027',required:4200,assigned:3612,plans:12,approved:10},{name:'Adabiyotshunoslik',faculty:'O‘zbek filologiyasi',term:'2-semestr',year:'2026/2027',required:3600,assigned:2880,plans:10,approved:8},{name:'Tarjima nazariyasi',faculty:'Tarjima nazariyasi',term:'1-semestr',year:'2026/2027',required:2800,assigned:2100,plans:8,approved:6},{name:'Jahon adabiyoti',faculty:'Tarjima nazariyasi',term:'2-semestr',year:'2026/2027',required:2400,assigned:1560,plans:6,approved:4}];
  const fmt=n=>new Intl.NumberFormat('uz-UZ').format(n);
  function filtered(){return demo.filter(r=>r.year===$('dash-year').value&&($('dash-term').selectedIndex===0||r.term===$('dash-term').value)&&($('dash-faculty').selectedIndex===0||r.faculty===$('dash-faculty').value));}
  function render(){const rows=filtered();const sum=k=>rows.reduce((s,r)=>s+r[k],0);const values=[['▦','Kafedralar',rows.length,'Namuna to‘plamdagi kafedralar'],['▣','Tasdiqlangan rejalar',sum('approved')+' / '+sum('plans'),'Tasdiqlangan / jami · demo'],['▥','Taqsimlangan yuklama',fmt(sum('assigned')),'Jami talab: '+fmt(sum('required'))+' soat'],['◷','Taqsimlanmagan yuklama',fmt(sum('required')-sum('assigned')),'Talab − taqsimlangan · soat']];$('dashboard-stats').replaceChildren();for(const [icon,label,value,note] of values){const c=document.createElement('div');c.className='stat';for(const [tag,text,cls] of [['small',label],['strong',value],['span',note],['span',icon,'stat-icon']]){const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;c.append(n);}$('dashboard-stats').append(c);}
    $('load-chart').replaceChildren();for(const r of rows){const b=document.createElement('div');b.className='bar-row';const n=document.createElement('span');n.textContent=r.name;const track=document.createElement('div');track.className='bar-track';const fill=document.createElement('div');fill.className='bar-fill';fill.style.width=(r.assigned/r.required*100)+'%';track.append(fill);track.setAttribute('role','img');track.setAttribute('aria-label',`${r.name}: ${r.assigned} / ${r.required} soat`);const v=document.createElement('b');v.textContent=Math.round(r.assigned/r.required*100)+'%';b.append(n,track,v);$('load-chart').append(b);}if(!rows.length){const p=document.createElement('p');p.className='empty-state';p.textContent='Tanlangan davr uchun namuna ma’lumot yo‘q.';$('load-chart').append(p);}}
  ['dash-year','dash-term','dash-faculty'].forEach(id=>$(id).onchange=render);render();
  const parts = new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Tashkent',day:'numeric',month:'numeric',year:'numeric'}).formatToParts(new Date()); const datePart=k=>parts.find(p=>p.type===k).value; const months=['yanvar','fevral','mart','aprel','may','iyun','iyul','avgust','sentabr','oktabr','noyabr','dekabr']; $('snapshot-date').textContent=datePart('day')+' '+months[Number(datePart('month'))-1]+' '+datePart('year');
  $('dashboard-export').onclick=()=>{const rows=[['DEMO — rasmiy hisobot emas'],['O‘quv yili',$('dash-year').value],['Semestr',$('dash-term').value],['Fakultet',$('dash-faculty').value],['Kafedra','Talab (soat)','Taqsimlangan (soat)','Taqsimlanmagan (soat)'],...filtered().map(r=>[r.name,r.required,r.assigned,r.required-r.assigned])];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'"+'$&').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='oquv-bolimi-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Filtrlangan demo hisobot CSV formatida yuklandi.');};
  go(location.hash.slice(1)||'dashboard');
})();
